export const BODY: string = "\n<p>فیویکن وہ چھوٹا آئیکن ہے جو آپ کے صفحے کے عنوان کے ساتھ براؤزر ٹیب میں ظاہر ہوتا ہے۔ یہ اکثر پہلی بصری تفصیل ہوتی ہے جسے زائرین دیکھتے ہیں، اور یہ آپ کی سائٹ کے ساتھ ہر جگہ جاتا ہے۔</p>\n<p>زیادہ تر زائرین فیویکن کے بارے میں شعوری طور پر کبھی نہیں سوچتے، پھر بھی غائب یا دھندلا فیویکن سائٹ کو نامکمل محسوس کراتا ہے۔ کرکرا آئیکن برانڈنگ سے پہلے دیکھ بھال اور پیشہ ورانہ پن کا اشارہ دیتا ہے۔</p>\n<p>یہ گائیڈ بتاتی ہے کہ فیویکن جنریٹر کیا کرتا ہے، مکمل آئیکن پیک میں کون سی فائلیں ہوتی ہیں، اور مفت ٹول سے لوگو کو تیار پیک میں کیسے بدلیں۔</p>\n<h2 id=\"what-is-a-favicon\">فیویکن کیا ہے؟</h2>\n<p>فیویکن چھوٹی تصویر فائل ہوتی ہے جو براؤزر انٹرفیس میں ویب سائٹ کی نمائندگی کرتی ہے۔ یہ ٹیب بار، بک مارک فہرست، تاریخ صفحہ، اور ہوم اسکرین شارٹ کٹ میں ظاہر ہوتی ہے۔</p>\n<p>کلاسک فیویکن فائل favicon.ico ہے، خاص کنٹینر فارمیٹ جو ایک فائل کے اندر کئی آئیکن سائز رکھ سکتا ہے۔ جدید براؤزر PNG آئیکن بھی قبول کرتے ہیں، اور مکمل پیک دونوں استعمال کرتا ہے۔</p>\n<p>16 بائی 16 پکسل پر فیویکن چھوٹا ہوتا ہے۔ یہ سائز ہر ڈیزائن فیصلے کو شکل دیتا ہے۔ باریک تفصیل غائب ہو جاتی ہے، پتلی لکیریں مٹ جاتی ہیں، اور چھوٹا متن ناقابل پڑھ ہو جاتا ہے۔ اچھا فیویکن سادہ ہوتا ہے۔</p>\n<p>بہت سی سائٹیں اپنے لوگو کا آسان ورژن فیویکن کے لیے استعمال کرتی ہیں۔ لمبے نام والا ورڈ مارک ایک حرف یا کمپیکٹ علامت بن جاتا ہے۔ تفصیلی مثال چھوٹی جگہ پر کام نہیں کرتی۔</p>\n<h2 id=\"why-every-website-needs-a-favicon\">ہر ویب سائٹ کو فیویکن کیوں چاہیے ہوتا ہے</h2>\n<p>فیویکن کے بغیر ویب سائٹ ٹیب میں عام گلوب یا خالی دستاویز آئیکن دکھاتی ہے۔ بہت سے ٹیب کھولنے والے زائرین آئیکن سے نیویگیٹ کرتے ہیں، اور خالی ٹیب تلاش کرنا مشکل ہوتا ہے۔</p>\n<p>فیویکن بک مارک اور براؤزر تاریخ میں بھی ظاہر ہوتے ہیں۔ جب قاری آپ کا صفحہ محفوظ کرے اور دنوں بعد واپس آئے تو آئیکن وہ بصری اشارہ ہوتا ہے جو آپ کے صفحے کی شناخت کرتا ہے۔</p>\n<p>موبائل آلے پر فیویکن اس آئیکن کو کھلاتا ہے جو اس وقت استعمال ہوتا ہے جب کوئی آپ کی سائٹ کو ہوم اسکرین میں بڑھائے۔ Apple آلے Apple Touch Icon استعمال کرتے ہیں، اور Android آلے مینی فیسٹ سے آئیکن پڑھتے ہیں۔</p>\n<p>سرچ انجن کبھی نتائج میں آپ کے صفحات کے ساتھ فیویکن دکھاتے ہیں۔ یہ چھوٹی برانڈنگ سطح ہے جس کی سیٹ اپ کے بعد کوئی قیمت نہیں۔ غائب فیویکن ضائع شدہ موقع ہے۔</p>\n<h2 id=\"what-the-favicon-generator-creates\">فیویکن جنریٹر کیا بناتا ہے</h2>\n<p>فیویکن جنریٹر ایک اپ لوڈ شدہ لوگو یا گرافک کو مکمل آئیکن پیک میں بدلتا ہے۔ یہ کئی سائز والی favicon.ico فائل، Apple Touch آئیکن، Android Chrome آئیکن، اور مینی فیسٹ بناتا ہے۔</p>\n<p>سب کچھ ایک ZIP ڈاؤن لوڈ میں پیک ہوتا ہے، اس لیے آپ کو تمام فائلیں ایک ساتھ ملتی ہیں۔ آپ favicon.ico یا apple-touch-icon.png جیسی انفرادی فائلیں بھی ڈاؤن لوڈ کر سکتے ہیں۔</p>\n<p>اس کی بنائی گئی favicon.ico فائل حقیقی کئی فریم والی ICO بائنری ہے، نام بدلا ہوا PNG نہیں۔ یہ اہمیت رکھتا ہے کیونکہ پرانے براؤزر اور کچھ ٹول حقیقی ICO کنٹینر کی توقع رکھتے ہیں۔</p>\n<p>جنریٹر مکمل طور پر آپ کے براؤزر میں کام کرتا ہے۔ آپ کا لوگو کبھی آپ کے آلے کو نہیں چھوڑتا، جو اہمیت رکھتا ہے جب آرٹ ورک غیر جاری شدہ برانڈ نشان یا کلائنٹ لوگو ہو۔</p>\n<h2 id=\"choosing-a-source-image\">ماخذ تصویر چننا</h2>\n<p>مربع PNG یا SVG لوگو تیز ترین نتائج دیتا ہے۔ SVG مثالی ہے کیونکہ یہ ہر سائز تک صاف پیمانہ کرتا ہے بغیر کنارے کھوئے، جبکہ اعلیٰ ریزولوشن PNG بھی اچھی طرح کام کرتا ہے۔</p>\n<p>اپنے لوگو کے سب سے بڑے ورژن سے شروع کریں جو آپ تلاش کر سکتے ہیں۔ 1024 بائی 1024 پکسل ماخذ 16 پکسل تک صاف سکڑتا ہے، جبکہ 64 پکسل ماخذ اوپر کھینچا جائے تو نرم ہو جاتا ہے۔</p>\n<p>شفاف پس منظر والے لوگو عام طور پر براؤزر ٹیب میں بہترین لگتے ہیں، کیونکہ نشان کے گرد ٹیب رنگ نظر آتا ہے۔ ٹھوس پس منظر بھی کام کر سکتا ہے، خاص طور پر جب لوگو خود پتلا ہو۔</p>\n<p>اگر آپ کا لوگو مستطیل ہو تو جنریٹر اسے کھینچنے کے بجائے مربع کینوس میں فٹ کرتا ہے۔ یہ تناسب ایماندار رکھتا ہے، مگر یہ کناروں پر خالی جگہ چھوڑ سکتا ہے۔</p>\n<h2 id=\"padding-corner-radius-and-background-fill\">پیڈنگ، کونے کا رداس، اور پس منظر بھرنا</h2>\n<p>پیڈنگ آپ کے لوگو اور آئیکن کینوس کے کنارے کے درمیان سانس لینے کی جگہ کنٹرول کرتی ہے۔ کناروں کو چھونے والا لوگو 16 پکسل پر تنگ لگتا ہے، اس لیے تھوڑی پیڈنگ اسے پڑھنے کے قابل رکھتی ہے۔</p>\n<p>کونے کا رداس آئیکن پس منظر کے کونوں کو گول کرتا ہے۔ چھوٹا رداس شکل کو نرم کرتا ہے، جبکہ بڑا رداس آئیکن کو دائرے میں بدل دیتا ہے۔ گول آئیکن جدید برانڈ کے لیے موزوں ہیں۔</p>\n<p>پس منظر بھرنا شفاف لوگو کے پیچھے رنگ سیٹ کرتا ہے۔ ٹھوس بھرنا آئیکن کو کسی بھی ٹیب رنگ پر نمایاں کرتا ہے، جو مفید ہوتا ہے جب لوگو خود پتلا یا ہلکا ہو۔</p>\n<p>یہ تینوں کنٹرول پیک کے ہر سائز کو ایک ساتھ اپ ڈیٹ کرتے ہیں۔ پیڈنگ ایک بار بدلیں اور 16 پکسل ٹیب آئیکن، 180 پکسل Apple آئیکن، اور 512 پکسل Android آئیکن سب بدل جاتے ہیں۔</p>\n<h2 id=\"light-and-dark-tab-previews\">ہلکے اور تاریک ٹیب پیش نظارے</h2>\n<p>جنریٹر آپ کا آئیکن ہلکے اور تاریک دونوں براؤزر ٹیب پس منظر پر دکھاتا ہے۔ یہ پیش نظارہ اہمیت رکھتا ہے کیونکہ تاریک لوگو تاریک ٹیب پر غائب ہو جاتا ہے، اور ہلکا لوگو ہلکے ٹیب پر غائب ہو جاتا ہے۔</p>\n<p>ڈاؤن لوڈ سے پہلے دونوں پیش نظارے چیک کریں۔ اگر آپ کا لوگو تاریک ہو تو ہلکا پس منظر بھرنا یا ہلکا خاکہ بڑھائیں تاکہ یہ تاریک موڈ سے بچے۔ اگر آپ کا لوگو ہلکا ہو تو الٹا کریں۔</p>\n<p>کچھ ڈیزائنر خاص طور پر اس مسئلے کو حل کرنے کے لیے نشان کے پیچھے معمولی پس منظر شکل بڑھاتے ہیں۔ برانڈ رنگ میں بھرا ہوا گول مربع آئیکن کو کسی بھی ٹیب پر مستقل شکل دیتا ہے۔</p>\n<p>پیش نظارہ سجاوٹ نہیں ہے۔ یہ سب سے عام فیویکن ناکامی کو پکڑتا ہے، جو آئیکن ہے جو ڈیزائن ٹول میں کامل لگتا ہے اور اصل براؤزر میں غائب ہو جاتا ہے۔</p>\n<h2 id=\"the-html-snippet-and-file-placement\">HTML اسنیپٹ اور فائل جگہ</h2>\n<p>پیک بنانے کے بعد آپ فائلیں اپنی ویب سائٹ پر اپ لوڈ کرتے ہیں اور اپنے صفحات کے head حصے میں HTML کا مختصر اسنیپٹ بڑھاتے ہیں۔ اسنیپٹ براؤزر کو بتاتا ہے کہ آئیکن کہاں ہیں۔</p>\n<p>فائلوں کی معمول کی جگہ آپ کی ویب سائٹ کا روٹ فولڈر ہے، وہی فولڈر جو آپ کے ہوم پیج کا ہے۔ براؤزر ڈیفالٹ سے روٹ پر favicon.ico تلاش کرتے ہیں، اس لیے وہاں رکھنا کام کرتا ہے۔</p>\n<p>اسنیپٹ سادہ HTML سائٹس اور React اور Next.js جیسے فریم ورک سے کام کرتا ہے۔ فریم ورک میں head حصہ ٹیمپلیٹ یا لے آؤٹ فائل میں رہتا ہے بجائے ہر صفحے کے۔</p>\n<p>فائل نام بالکل ویسے رکھیں جیسے بنائے گئے تھے۔ اسنیپٹ اپ ڈیٹ کیے بغیر فائل کا نام بدلنا لنک توڑ دیتا ہے، اور براؤزر ڈیفالٹ آئیکن پر واپس جاتا ہے۔ اگر آپ فائل منتقل کریں تو اسنیپٹ بھی اپ ڈیٹ کریں۔</p>\n<h2 id=\"apple-touch-icons-and-android-icons\">Apple Touch آئیکن اور Android آئیکن</h2>\n<p>Apple آلے 180 بائی 180 پکسل Apple Touch Icon استعمال کرتے ہیں جب زائرین آپ کی سائٹ کو ہوم اسکرین میں بڑھائیں۔ Apple اس آئیکن میں شفافیت کو نظر انداز کرتا ہے اور شفاف علاقوں کو بھرتا ہے۔</p>\n<p>Android آلے ویب مینی فیسٹ سے آئیکن پڑھتے ہیں، ہوم اسکرین کے لیے 192 بائی 192 اور اسپلش اسکرین اور انسٹال پرامپٹ کے لیے 512 بائی 512 استعمال کرتے ہیں۔ دونوں سائز پیک میں شامل ہیں۔</p>\n<p>یہ بڑے آئیکن اہمیت رکھتے ہیں کیونکہ وہ ٹیب فیویکن سے کہیں بڑے دکھائے جاتے ہیں۔ 16 پکسل پر اچھا پڑھنے والا نشان 512 پکسل پر خالی لگ سکتا ہے، اور تفصیلی نشان چھوٹے سائز پر ناکام ہو سکتا ہے۔</p>\n<p>پیک انسٹال کرنے کے بعد اصل فون پر ہوم اسکرین آئیکن ٹیسٹ کریں۔ سائٹ کو ہوم اسکرین میں بڑھائیں، آئیکن کو اپنی دوسری ایپس کے ساتھ دیکھیں، اور چیک کریں کہ یہ صاف اور پہچاننے کے قابل ہے۔</p>\n<h2 id=\"the-site-webmanifest-file\">site.webmanifest فائل</h2>\n<p>site.webmanifest چھوٹی JSON فائل ہے جو آپ کی سائٹ کو انسٹال کرنے والی ویب ایپ کے طور پر بیان کرتی ہے۔ یہ سائٹ کا نام، تھیم رنگ، اور آئیکن فائلیں ان کے سائز کے ساتھ درج کرتی ہے۔</p>\n<p>جنریٹر یہ فائل آپ کے لیے لکھتا ہے، بشمول 192 اور 512 پکسل آئیکن اور درست سائز لیبل۔ آپ کو JSON ہاتھ سے لکھنے یا مینی فیسٹ فارمیٹ یاد رکھنے کی ضرورت نہیں۔</p>\n<p>مینifest میں تھیم رنگ آپ کی سائٹ کھلنے پر Android پر براؤزر ٹول بار کو رنگتا ہے۔ اپنے برانڈ سے میل کھانے والا رنگ چنیں، اور براؤزر کروم مل جاتا ہے۔</p>\n<p>اگر آپ بعد میں سائٹ کا نام یا برانڈ رنگ بدلیں تو مینی فیسٹ اپ ڈیٹ کریں اور پیک دوبارہ بنائیں۔ مینی فیسٹ سادہ متن ہے، اس لیے نام کے لیے چھوٹی ایڈٹ کافی ہوتی ہے۔</p>\n<h2 id=\"common-favicon-mistakes\">عام فیویکن غلطیاں</h2>\n<p>سب سے عام غلطی چھوٹے متن والا تفصیلی لوگو اپ لوڈ کرنا ہے۔ 16 پکسل پر ٹیگ لائن سرمئی شور بن جاتی ہے اور پتلا ورڈ مارک دھبہ بن جاتا ہے۔ ڈیزائن کو آسان کریں۔</p>\n<p>دوسری غلطی کم ریزولوشن ماخذ استعمال کرنا ہے۔ Android آئیکن کے لیے 512 پکسل تک کھینچی گئی 32 پکسل تصویر نرم اور شوقیہ لگتی ہے۔ ہمیشہ سب سے بڑے ماخذ سے شروع کریں۔</p>\n<p>تیسری غلطی Apple Touch Icon پس منظر بھولنا ہے۔ iPhone ہوم اسکرین پر شفاف لوگو کو سیاہ کونے ملتے ہیں جو رینڈرنگ بگ کی طرح لگتے ہیں۔ اسے ٹھوس پس منظر بھرنا دیں۔</p>\n<p>آخر میں، بہت سی سائٹیں مینی فیسٹ مکمل چھوڑ دیتی ہیں اور حیران ہوتی ہیں کہ Android آئیکن کے بجائے اسکرین شاٹ کیوں دکھاتا ہے۔ مینی فیسٹ وہ فائل ہے جسے Android پڑھتا ہے، اس لیے اس کے بغیر کوئی آئیکن نہیں۔</p>\n<h2 id=\"updating-a-favicon-without-cache-trouble\">کیشے کی پریشانی کے بغیر فیویکن اپ ڈیٹ کرنا</h2>\n<p>براؤزر فیویکن کو جارحانہ طور پر کیشے کرتے ہیں، کبھی ہفتوں تک۔ نیا پیک اپ لوڈ کرنے کے بعد آپ کا اپنا براؤزر پرانا آئیکن دکھاتا رہ سکتا ہے اگرچہ فائلیں بدل گئی ہوں۔</p>\n<p>سب سے آسان حل صفحے کا ہارڈ ریفریش ہے، یا سائٹ کے لیے براؤزر کیشے صاف کرنا ہے۔ Chrome میں Ctrl اور Shift اور R کے ساتھ ہارڈ ریفریش اکثر نیا آئیکن مجبور کرتا ہے۔</p>\n<p>زائرین کے لیے نیا آئیکن تب ظاہر ہوتا ہے جب ان کا کیشے ختم ہو یا وہ تازہ آلے پر جائیں۔ آپ آئیکن لنک میں ورژن کوئری بڑھا کر اسے تیز کر سکتے ہیں۔</p>\n<p>جب آپ دوبارہ برانڈ کریں تو ایک فائل بدلنے کے بجائے پورا پیک دوبارہ بنائیں۔ جزوی اپ ڈیٹ بے میل سائز چھوڑتا ہے، ٹیب میں نیا نشان اور ہوم اسکرین پر پرانا نشان۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: فیویکن پیک چیک لسٹ</h2>\n<p>کم از کم 512 پکسل والے مربع PNG یا SVG لوگو سے شروع کریں۔ پیڈنگ سیٹ کریں تاکہ نشان سانس لے، پس منظر بھرنا چنیں جو ہلکے اور تاریک دونوں ٹیب سے بچے، اور دونوں پیش نظارے چیک کریں۔</p>\n<p>ZIP مواد کو اپنی سائٹ روٹ پر اپ لوڈ کریں، HTML اسنیپٹ کو اپنے مشترکہ head ٹیمپلیٹ میں چسپاں کریں، اور Android کے لیے مینی فیسٹ شامل کریں۔ پھر ٹیب آئیکن، ہوم اسکرین آئیکن، اور بک مارک ٹیسٹ کریں۔</p>\n<p>مرحلہ بہ مرحلہ واک تھرو کے لیے <a href=\"/ur/blog/favicon-kaise-banayein/\">How to Create a Favicon</a> پڑھیں، اور ہر سائز کی وضاحت کے لیے <a href=\"/ur/blog/favicon-sizes-wazahat/\">Favicon Sizes Explained: 16×16 to 512×512</a> پڑھیں۔ اپنا پیک <a href=\"/ur/favicon-generator/\">favicon generator</a> سے بنائیں۔</p>\n";

